local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Greetings to you. I seek the service of a powerful warrior. Are you a warrior? If not then be gone.")
  end
  if e.message:findi("i am a warrior") then
    e.self:Say("Excellent. I see that you are a seasoned veteran of many battles. I admire your strength and ferocity. Life is but a series of battles, is it not?")
  end
  if e.message:findi("life is a series of battles") then
    e.self:Say("We share the same view then. I wish to test your skills in battle. Not with me of course, for I will destroy you where you stand. Instead I wish for you to retrieve some trinkets for me and once I have them I will reward you handsomely with a helm, a breastplate, armplates, bracers, gauntlets, greaves, or boots.")
  end
  if e.message:findi("helm") then
    e.self:Say("All I require are an ancient tarnished plate helmet and three crushed coral pieces. This should be a small task for one such as you. Go now and I shall await your return.")
  end
  if e.message:findi("breastplate") then
    e.self:Say("As the resolve of your discipline and strength shall endure through a battle, so shall this breastplate. All that is required are an ancient tarnished breastplate, and three flawless diamonds. Do this quickly so that you may return to the field of battle.")
  end
  if e.message:findi("armplate") then
    e.self:Say("So, a pair of armplates, is what you require? Well, I require ancient tarnished plate vambraces, and three flawed emeralds before you may receive it. May your deeds be spread throughout the lands!")
  end
  if e.message:findi("bracer") then
    e.self:Say("Bracers for the mighty? Retrieve these components and I shall forge the item for you. Bring me ancient tarnished plate bracers and three crushed flame emeralds.")
  end
  if e.message:findi("gauntlet") then
    e.self:Say("Mighty gauntlets to aid in obliterating your foes, eh? It is no easy task but I shall require a pair of ancient tarnished plate gauntlets and three crushed topazes. Hurry along, " .. e.other:GetRaceName() .. ".")
  end
  if e.message:findi("greaves") then
    e.self:Say("Strength and balance are important, are they not? I shall help give you an advantage with these greaves. Gather three flawed sea sapphires and ancient tarnished plate greaves.")
  end
  if e.message:findi("boots") then
    e.self:Say("'A pair of boots you shall have once you have acquired a pair of ancient tarnished plate boots and three crushed black marbles.")
  end
end

